window.FILM_WORK_PROMPTS={"work_id":"src-aa81db36953974bb","records":[{"work_id":"src-aa81db36953974bb","frame_id":"FG-aa30344041af49a7","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (474).jpg","source_page":"https://film-grab.com/2014/08/06/i-am-love/","scene":"长餐桌两侧站立与坐着多位人物，室内墙壁挂有大幅挂毯，上方悬挂水晶吊灯，背景可见壁炉与拱门。","analysis":"长餐桌呈对角线构图，前景人物全身或大半身可见，远处人物较小。画面采用平视角度，室内光线柔和，左侧窗户透入自然光，水晶吊灯反射出高光。人物衣着颜色多样，包括深色西装、红色上衣、米色毛衣等，与暖色调墙壁形成对比。","prompt":"室内长餐桌场景，两侧站立与坐着多位人物，前景左侧站立一名穿深色西装的男子，右侧站立一名穿深色西装的男子。餐桌中央摆放着餐具、绿色玻璃杯和银色器皿。背景墙壁挂有大幅挂毯，上方悬挂水晶吊灯，远处可见壁炉与拱门。室内光线柔和，左侧窗户透入自然光，整体色调偏暖，人物衣着颜色多样，包括红色、米色、深色等。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:00:26-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (474).jpg","observed_dimensions":[1280,688],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.515,"observed_resolution":"normal","observation_limits":[],"id":"VP-cad0fdd3938e5c0a","origin":"visual"},{"work_id":"src-aa81db36953974bb","frame_id":"FG-47580bf3502a0f49","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (484).jpg","source_page":"https://film-grab.com/2014/08/06/i-am-love/","scene":"灰蓝色天空背景下，哥特式建筑尖塔林立，四座高耸的尖顶顶端各站立一个深色人物剪影，下方密集排列着较小的装饰性尖顶结构。","analysis":"画面以大面积灰蓝色天空为背景，占据约七成画面空间。四座高耸的哥特式尖塔呈不规则分布，左侧两座较高且靠近，右侧两座较矮且分散。每座尖塔顶端站立一个全身可见的人物剪影，呈站立姿态，身形细长。下方可见密集的小型尖顶和十字装饰结构。整体光线均匀平淡，无明显阴影，色调偏冷灰，人物与建筑均为深色剪影，与浅色天空形成对比。","prompt":"灰蓝色阴天天空占据画面大部分空间，下方是哥特式大教堂的尖顶群。四座高耸的细长尖塔从画面底部升起，左侧两座较高且间距较近，右侧两座较矮且间距较远，每座尖塔顶端各站立一个深色人物剪影，人物全身可见，呈直立姿态，身形细长如针。尖塔表面有复杂的镂空装饰纹理。画面下方密集排列着众多较小的尖顶和十字形装饰结构，形成锯齿状天际线。整体色调冷灰，光线均匀无强烈阴影，人物与建筑均为深灰色剪影，与浅灰蓝色天空形成清晰对比，画面氛围静谧肃穆。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:00:35-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (484).jpg","observed_dimensions":[1280,688],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.475,"observed_resolution":"normal","observation_limits":[],"id":"VP-aad57b98d8c2ebe8","origin":"visual"},{"work_id":"src-aa81db36953974bb","frame_id":"FG-b2c614e7f2d54856","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (482).jpg","source_page":"https://film-grab.com/2014/08/06/i-am-love/","scene":"一名身穿橙色连衣裙、外搭浅色开衫的女子站在铺砌的广场上。她身旁右侧是一根粗壮的深色金属灯柱，底部环绕着红白相间的花坛，背景可见石质栏杆和模糊的树木。","analysis":"画面采用平视视角，人物位于画面左侧三分之一处，全身可见，身形在画面中占比适中。右侧前景的灯柱与花坛占据了显著空间，形成了视觉平衡。光线为明亮的自然日光，在人物身上和地面投下柔和阴影，整体色调温暖，背景略微虚化以突出主体。","prompt":"一名金发女子站在户外铺砌的广场上，她身穿鲜艳的橙色中长款连衣裙，外搭一件米白色针织开衫，戴着墨镜，肩上挎着包，姿态自然地站立。画面右侧前景矗立着一根深灰色的复古金属灯柱，柱身有磨损痕迹，底部是一个圆形的石砌花坛，里面种满了红色和白色的低矮花卉。背景是一道米黄色的石质栏杆，栏杆后隐约可见绿色的棕榈树叶和停放的车辆。阳光充足，光影柔和，地面有斑驳的树影，整体呈现出温暖明亮的日间氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:00:42-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (482).jpg","observed_dimensions":[1280,688],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.522,"observed_resolution":"normal","observation_limits":[],"id":"VP-f074cd378a18461f","origin":"visual"},{"work_id":"src-aa81db36953974bb","frame_id":"FG-2ebc46f9219dad91","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (470).jpg","source_page":"https://film-grab.com/2014/08/06/i-am-love/","scene":"一朵盛开的白色雏菊占据画面左侧，黄色花心清晰可见，花瓣间停驻着微小的昆虫。背景为深褐色与暗绿色的模糊色块，光线柔和，营造出静谧的自然氛围。","analysis":"构图采用偏左布局，花朵主体清晰锐利，占据画面约三分之一宽度。背景完全虚化，形成强烈的景深对比，突显主体细节。光线从上方或侧方照射，花瓣呈现自然的明暗过渡，花心黄色饱和度高。整体色调偏暖，暗部深沉，亮部柔和，无强烈高光。","prompt":"一朵盛开的白色雏菊位于画面左侧，花瓣细长洁白，呈放射状排列，中心是密集的黄色花蕊。花瓣上可见细微的纹理和几处微小的昆虫。背景是深褐色与暗绿色交织的模糊色块，完全失焦，营造出深邃的空间感。光线柔和自然，从上方洒落，使花瓣边缘呈现半透明质感，花心明亮。整体画面色调温暖，对比度适中，焦点集中在花朵细节上，展现出微观自然界的静谧与精致。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:00:50-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (470).jpg","observed_dimensions":[1280,688],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.514,"observed_resolution":"normal","observation_limits":[],"id":"VP-e88389fc52530010","origin":"visual"},{"work_id":"src-aa81db36953974bb","frame_id":"FG-aba7ad653604d1ec","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (427).jpg","source_page":"https://film-grab.com/2014/08/06/i-am-love/","scene":"昏暗室内，两名穿深色长裙的人物站立在大型木制家具前，一人抬手整理另一人头发，墙上挂着多幅带框画像。","analysis":"画面主体为两名站立人物的上半身及头部，背景占据约60%画面。左侧人物手臂高举，右侧人物侧身站立。光线从左侧射入，形成明显的明暗对比，人物面部和手臂受光，背景家具和墙面处于阴影中。色调偏暖黄，整体氛围沉静压抑。","prompt":"昏暗的古典室内，两名身穿深色长裙的人物站立在大型木制衣柜前，左侧人物手臂高举正在整理右侧人物的头发，右侧人物侧身站立面向右方。背景墙上挂着四幅带金色画框的画像，两幅方形两幅椭圆形。画面光线从左侧射入，人物面部和手臂呈现暖黄色调，背景家具和墙面处于阴影中，整体色调偏暗，氛围沉静。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:00:56-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (427).jpg","observed_dimensions":[1280,688],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.507,"observed_resolution":"normal","observation_limits":[],"id":"VP-c886bf84c183735d","origin":"visual"},{"work_id":"src-aa81db36953974bb","frame_id":"FG-5769003a811294f4","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (474).jpg","source_page":"https://film-grab.com/2014/08/06/i-am-love/","scene":"昏暗的室内空间，中央放置一架黑色三角钢琴，琴盖打开，谱架上立着乐谱。背景是挂着白色纱帘的窗户，两侧墙壁设有深色书架，摆放着书籍，墙上装饰有壁灯。","analysis":"画面采用中心对称构图，钢琴位于视觉中心，琴身占据画面中下部。背景窗户透入强烈的自然光，形成逆光效果，使钢琴和前景处于剪影状态。两侧书架和墙壁在暗部，细节模糊，仅能辨识轮廓。整体色调偏冷，明暗对比强烈，营造出静谧、压抑的氛围。","prompt":"昏暗的室内场景，中央放置一架黑色三角钢琴，琴盖打开，谱架上立着乐谱，琴凳位于钢琴前方。背景是一扇挂着白色纱帘的窗户，强烈的自然光从窗外射入，形成逆光效果，使钢琴和前景处于剪影状态。两侧墙壁设有深色书架，摆放着书籍，墙上装饰有壁灯。整体色调偏冷，明暗对比强烈，营造出静谧、压抑的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T21:56:32+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (474).jpg","observed_dimensions":[1280,688],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.453,"observed_resolution":"normal","observation_limits":[],"id":"VP-003ccb0430641f2e","origin":"visual"},{"work_id":"src-aa81db36953974bb","frame_id":"FG-897941dce9a93149","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (484).jpg","source_page":"https://film-grab.com/2014/08/06/i-am-love/","scene":"金发女子坐在铺满落叶的绿草地上，身穿粉色长袖上衣与牛仔裤，身旁放着棕色皮包，背景是模糊的树木与围栏。","analysis":"画面采用平视角度，人物位于画面中央，全身可见，坐姿自然。前景是清晰的草地与落叶，中景是人物主体，背景虚化。光线柔和，色彩以绿色草地和粉色衣物为主，形成冷暖对比，光影层次丰富，营造出宁静的氛围。","prompt":"一位金发女子坐在铺满落叶的绿草地上，身穿粉色长袖上衣，领口有红白条纹，下身穿蓝色牛仔裤，脚穿黑色运动鞋。她双腿交叉，双手自然放在腿上，身旁放着一个棕色皮包。背景是模糊的树木和白色围栏，阳光透过树叶洒在草地上，形成斑驳的光影。画面色彩柔和，以绿色和粉色为主调，营造出一种宁静、自然的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T21:56:42+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (484).jpg","observed_dimensions":[1280,688],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.509,"observed_resolution":"normal","observation_limits":[],"id":"VP-f8be5618ab316711","origin":"visual"},{"work_id":"src-aa81db36953974bb","frame_id":"FG-91d8c11c06690e69","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (482).jpg","source_page":"https://film-grab.com/2014/08/06/i-am-love/","scene":"一座东正教风格教堂的顶部，数个洋葱头圆顶在灰白天空下矗立，圆顶表面覆盖着鳞片状纹理，顶端竖立着十字架，画面右侧有茂密的绿色树冠遮挡部分建筑。","analysis":"画面主体为教堂建筑的上半部分，占据画面中心及左侧区域。构图上，圆顶呈高低错落的三角形布局，右侧的大片绿树与左侧的建筑形成视觉平衡。天空布满灰白色的云层，光线柔和漫射，没有强烈的明暗对比。几条黑色的电线横穿天空，增加了画面的层次感。","prompt":"这是一张写实风格的建筑摄影静帧。画面中心是一座东正教教堂的顶部，拥有多个标志性的洋葱头圆顶。圆顶表面呈现出复杂的鳞片状或马赛克纹理，颜色为灰褐色与暗金色交织，每个圆顶顶端都竖立着细长的金属十字架。建筑主体为白色，带有拱形窗户。画面右侧是一棵枝叶茂密的常绿乔木，深绿色的叶片占据了右下角的大部分空间，与教堂的冷色调形成对比。背景是阴沉的灰白色天空，云层厚重，几条黑色的电线水平横穿画面上方。整体光线均匀柔和，色彩饱和度较低，呈现出一种静谧、略带忧郁的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T21:56:50+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (482).jpg","observed_dimensions":[1280,688],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.497,"observed_resolution":"normal","observation_limits":[],"id":"VP-547780772b95a614","origin":"visual"},{"work_id":"src-aa81db36953974bb","frame_id":"FG-4742984b8a255a91","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (464).jpg","source_page":"https://film-grab.com/2014/08/06/i-am-love/","scene":"一名穿深色西装、系深蓝领带的男子坐在桌前，神情严肃地注视前方。前景右侧有大面积模糊的深色背影遮挡，桌上摆放着玻璃瓶和杯子，背景虚化。","analysis":"画面采用过肩视角，右侧前景被巨大的模糊深色色块占据，形成强烈的虚实对比。左侧男子上半身清晰可见，占据画面约三分之一，面部处于焦点中心。光线柔和偏冷，背景呈现灰蓝色调，营造出一种冷静、压抑的对话氛围。","prompt":"电影质感静帧，冷色调室内场景。画面左侧一名年轻男子，深棕色短发，身穿深色细条纹西装，内搭浅粉色衬衫，系深蓝色领带。他正襟危坐，面部表情严肃，眼神专注地望向右前方。画面右侧前景被一个巨大的、极度失焦的深色人物背影占据，形成强烈的遮挡和景深效果。前景桌面上可见几个模糊的玻璃瓶和透明玻璃杯。背景虚化，呈现灰蓝色的冷光环境，整体氛围沉静且充满张力。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T21:56:58+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (464).jpg","observed_dimensions":[1280,688],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.495,"observed_resolution":"normal","observation_limits":[],"id":"VP-02381c5a5ae0ab28","origin":"visual"},{"work_id":"src-aa81db36953974bb","frame_id":"FG-50e38d6ad88ed8d5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (423).jpg","source_page":"https://film-grab.com/2014/08/06/i-am-love/","scene":"阴沉天色下，一条笔直墓园小径通向远处白色教堂，两侧排列着墓碑与茂密深色树木，小径中央有一个孤独的人影正背对镜头向教堂方向行走。","analysis":"画面采用严格的中心对称构图，两侧深色树木形成天然画框，将视线引向中央的白色建筑。人物位于画面中下部，全身可见，身形极小，与巨大的环境形成强烈对比。整体色调偏冷暗，以深绿和灰黑为主，仅教堂呈现较亮的灰白色，光线平淡无强烈阴影，营造出压抑、肃穆的视觉氛围。","prompt":"一张阴郁的墓园场景图，画面中心是一条笔直延伸的灰色小径，尽头矗立着一座带有圆形玫瑰窗和尖顶的白色教堂建筑。小径两侧排列着密集的深色墓碑和低矮灌木，更外侧是高大茂密的深绿色针叶林，树木在两侧形成对称的暗色边框。小径中央远处有一个身穿深色衣物的人影，全身可见，正背对镜头向教堂方向行走。天空呈现阴沉的灰蓝色，整体光线昏暗柔和，色彩饱和度低，以冷色调为主，营造出一种孤独、肃穆且略带压抑的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T21:57:06+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (423).jpg","observed_dimensions":[1280,688],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.476,"observed_resolution":"normal","observation_limits":[],"id":"VP-15cbd9ec61b9c829","origin":"visual"}]};